contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public {
        address before = c.owner();
        bool reverted;
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            assert(success && c.owner() == newOwner);
        } catch {
            reverted = true;
            assert(c.owner() == before);
        }
        assert(reverted ? (c.owner() == before) : (c.owner() == newOwner));
    }
    receive() external payable {}
}

