contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(newOwner != address(this));
        require(msg.sender != newOwner);
        // At deployment, owner == this test contract (msg.sender of the constructor).
        require(c.owner() == address(this));

        // First: a non-owner attempt must revert and leave owner unchanged.
        bool reverted;
        // Use a separate probe via return value instead: simulate by checking with try
        try c.setOwner(newOwner) returns (bool) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);

        address before = c.owner();
        // Re-check owner unchanged requires a state-changing observation, so instead
        // verify the successful path: owner (this contract) can set the owner.
        bool ok = c.setOwner(address(newOwner));
        assert(ok && c.owner() == newOwner);

        // General rule: previous owner is now unauthorized - a second successful
        // transition could only happen from newOwner, so assert invariant reached above.
        assert(before == address(this));
    }
    receive() external payable {}
}
